import{_ as n,o as i,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Zeichnen mit SVG-Line und SVG LineBox","description":"","frontmatter":{"title":"Zeichnen mit SVG-Line und SVG LineBox"},"headers":[],"relativePath":"projects/grafik-visual-studio/zeichnen.md","filePath":"projects/grafik-visual-studio/zeichnen.md","lastUpdated":1792849697000}'),s={name:"projects/grafik-visual-studio/zeichnen.md"};function d(a,e,u,l,o,g){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="zeichnen-svg-line-und-svg-linebox" tabindex="-1">Zeichnen: SVG-Line und SVG LineBox <a class="header-anchor" href="#zeichnen-svg-line-und-svg-linebox" aria-label="Permalink to &quot;Zeichnen: SVG-Line und SVG LineBox&quot;">​</a></h1><p>Die vollständigen Anleitungen stehen auf eigenen Seiten: <a href="./svg-line">SVG-Line – Verbindungslinien und Animation</a> und <a href="./svg-linebox">SVG LineBox – Werte sammeln und weitergeben</a> · <a href="./svg-linebox-math">SVG LineBox Math</a>. Auf der LineBox-Seite sind auch die Videos für Editor und Runtime eingebunden. Diese Übersicht bleibt für bestehende Links erhalten.</p><p>Das Linien-Widget steht in der Palette als <strong>HA Grafik – Spezial → SVG-Line</strong>. Damit kannst du zum Beispiel zwei Solarpanels optisch mit einem Wechselrichter verbinden oder mehrere Ströme an einem Sammelpunkt zusammenführen. SVG-Line liest für die Animation optional eine Home-Assistant-Entität; die SVG LineBox kann die Zahlenwerte mehrerer Linien addieren und an eine Ausgangslinie weitergeben.</p><h2 id="eine-verbindung-zeichnen" tabindex="-1">Eine Verbindung zeichnen <a class="header-anchor" href="#eine-verbindung-zeichnen" aria-label="Permalink to &quot;Eine Verbindung zeichnen&quot;">​</a></h2><ol><li>Füge <strong>SVG-Line</strong> ein und wähle sie aus. Ihre beiden Endpunkte sind als ziehbare Kreise sichtbar. Ziehe einen freien Endpunkt auf einen Andockpunkt eines anderen Widgets. Alternativ kannst du unter <strong>Start</strong> und <strong>Ziel</strong> ein Widget samt Andockpunkt auswählen oder freie X-/Y-Koordinaten eingeben.</li><li>Aktiviere am Ziel-Widget die Eigenschaftengruppe <strong>Andockpunkte</strong>. Bei neuen Widgets sind alle zwölf Positionen zunächst aus. <strong>Alle Punkte</strong> schaltet sie gemeinsam ein oder aus und zeigt bei einer Teilauswahl einen gemischten Zustand. Die Punkte lassen sich auch einzeln aktivieren: links/rechts jeweils oben, Mitte, unten; oben/unten jeweils bei 1/4, Mitte und 3/4 der Breite. Der Haken in der Gruppenüberschrift aktiviert oder deaktiviert den ganzen Bereich. Mehrfachbelegung, maximale Verbindungen, Spurabstand und dauerhafte Anzeige sind einstellbar.</li><li>Wähle die <strong>Pfadart</strong>: gerade, automatisch rechtwinklig, Kurve oder manueller Zickzack-/Mehrpunktpfad. Ein Klick auf die Linie öffnet mittig den Dialog <strong>Zwischenpunkt</strong> oder <strong>Sammelpunkt</strong>; „Zwischenpunkt“ ist vorausgewählt. Nach <strong>OK</strong> entsteht ein verschiebbarer Zwischenpunkt und der Pfad wechselt in den manuellen Mehrpunktmodus. Die Punkte lassen sich zusätzlich im Eigenschaften-Editor benennen und per X/Y setzen.</li></ol><p>Ein aktivierter <strong>Sammelpunkt</strong> kann von einer anderen Linie als Start oder Ziel gewählt werden. Du kannst auch einen freien Linienendpunkt auf den sichtbaren Sammelpunkt ziehen: Er rastet dort ein und speichert die Kopplung. Eine Kreuzung oder räumliche Nähe allein koppelt Linien niemals. Deaktivierst du den Sammelpunkt, rastet dort keine neue Linie ein. Mehrere Linien können zu einem aktivierten Sammelpunkt führen. Linien, die den Punkt bisher nur optisch berühren, musst du einmal neu andocken.</p><h2 id="aussehen-und-fluss" tabindex="-1">Aussehen und Fluss <a class="header-anchor" href="#aussehen-und-fluss" aria-label="Permalink to &quot;Aussehen und Fluss&quot;">​</a></h2><ul><li><strong>Linie:</strong> Grundfarbe, zweite Animationsfarbe, Dicke, Deckkraft, durchgezogen/gestrichelt/gepunktet, Strich- und Lückenlänge, Linienenden sowie Eckenradius.</li><li><strong>Pfeilspitzen:</strong> Anfang und Ende getrennt als keine, gefüllter oder offener Pfeil oder Kreis; Größe und Farbe sind einstellbar.</li><li><strong>Animation:</strong> Zweifarbenfluss, laufende Striche, Puls oder Lichtpunkt. Unter <strong>Richtungsquelle</strong> ist genau eine Option aktiv: <strong>Manuell</strong> mit Richtung und Dauer, <strong>Zahlen-Entität</strong> oder <strong>Bool-Entität</strong>. Bei einer Zahlen-Entität bedeutet positiv Anfang → Ende, negativ Ende → Anfang und null Stillstand. Der Betrag geteilt durch <strong>Teiler</strong> (Standard 1) ergibt die Zyklen pro Sekunde, begrenzt auf 0,05 bis 20. Beispiel: 1000 W ÷ 100 = 10 Zyklen/s. Die Bool-Entität wählt mit <code>on</code>/<code>true</code>/<code>1</code> vorwärts und mit <code>off</code>/<code>false</code>/<code>0</code> rückwärts; die Zuordnung kann umgekehrt werden. Nicht verfügbare oder ungültige Zustände halten die Animation an. Pfeilspitzen folgen der aktiven Richtung. Die Runtime liest die ausgewählte HA-Entität regelmäßig neu. Mit <strong>Animationstakt der Hauptlinie übernehmen</strong> folgt eine Nebenlinie dem Takt ihrer Hauptlinie und behält bei laufender Animation ihre eigenen Farben. Ist sie an deren Sammelpunkt gekoppelt und die Hauptlinie nicht animiert, stoppt auch die Nebenlinie und zeigt die Grundfarbe der Hauptlinie, einschließlich der Pfeilspitzen. Ihre eigenen Farb- und Animationseinstellungen bleiben gespeichert und gelten nach dem Lösen der Kopplung wieder. Die Synchronisierung bietet gleichen Takt oder Ankunft am Sammelpunkt. Bei manueller Richtung zu einem Sammelpunkt richtet sich die Animation automatisch auf diesen Punkt aus.</li><li><strong>Kreuzung und Stapelung:</strong> Überlagerung, optische Lücke oder Brücke/Bogen sowie z-index-Modus „automatisch“, „darüber“, „darunter“ oder manuell. Ein höherer z-index liegt optisch vor einem niedrigeren; er erzeugt keine Verbindung.</li></ul><h2 id="bearbeiten" tabindex="-1">Bearbeiten <a class="header-anchor" href="#bearbeiten" aria-label="Permalink to &quot;Bearbeiten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aktion</th><th>Bedienung</th></tr></thead><tbody><tr><td>Freien Endpunkt bewegen</td><td>Kreis ziehen oder fokussierten Kreis mit den Pfeiltasten bewegen; <code>Umschalt</code> erhöht die Schrittweite von 1 auf 10 Pixel.</td></tr><tr><td>Angedockten Endpunkt lösen</td><td><code>Strg</code> gedrückt halten und den Kreis ziehen; <code>Strg</code> plus Pfeiltaste funktioniert ebenfalls.</td></tr><tr><td>Zwischenpunkt verschieben</td><td>Linie auswählen und den Punkt ziehen.</td></tr><tr><td>Ganze Linie verschieben</td><td>Auf die Linie drücken und ziehen. Vorherige Start-/Ziel-Andockungen werden dabei gelöst.</td></tr><tr><td>Linienpunkt hinzufügen</td><td>Linie ohne Ziehen anklicken, Punkttyp wählen und mit <strong>OK</strong> bestätigen.</td></tr></tbody></table><p>Das Widget ist experimentell. Die Darstellung von Kreuzungen und synchronisierten Animationen kann je nach Pfadverlauf und Browser noch verfeinert werden.</p><h2 id="linebox-als-unsichtbarer-verteiler" tabindex="-1">SVG LineBox als unsichtbarer Verteiler <a class="header-anchor" href="#linebox-als-unsichtbarer-verteiler" aria-label="Permalink to &quot;SVG LineBox als unsichtbarer Verteiler {#linebox-als-unsichtbarer-verteiler}&quot;">​</a></h2><p>Der Editor aktualisiert die Zustände der gewählten Zahlen- und Bool-Entitäten regelmäßig. So lassen sich SVG-Line-Animationen und der berechnete SVG LineBox-Wert bereits vor dem Wechsel in die Runtime prüfen.</p><p><strong>HA Grafik – Spezial → SVG LineBox</strong> ist im Editor sichtbar und verschiebbar. In der Runtime bleibt ihr Kasten unsichtbar; die angeschlossenen Leitungen treffen sich in ihrer Mitte. Dort liegt standardmäßig ein Kreis über den Linienenden und verdeckt deren kantigen Abschluss. Unter <strong>Verbindungspunkt</strong> kannst du ihn ausblenden sowie Durchmesser, Füllfarbe, Randfarbe und Randbreite einstellen. Bei dicken Linien wächst der Kreis bei Bedarf so weit, dass er die Enden weiterhin verdeckt. <strong>Ausgabewert anzeigen</strong> bietet die Positionen <strong>Aus</strong> (Standard), <strong>Über dem Kreis</strong> und <strong>Unter dem Kreis</strong>. Der Wert zeigt die signierte Summe der Eingänge und aktualisiert sich in der Runtime auch während einer Sliderbewegung. Die SVG LineBox besitzt dieselben zwölf Andockpositionen wie andere Widgets. Anfangs sind alle aus. Aktiviere unter <strong>Andockpunkte</strong> nur die benötigten Positionen. Unter <strong>Anschlüsse</strong> erscheint dann für jeden aktiven Punkt die Rolle <strong>Eingang</strong>, <strong>Nullstellung</strong> oder <strong>Ausgang</strong>. Nullstellung ist die Voreinstellung und nimmt nicht an der Berechnung teil. Deaktivierte Punkte haben keine Rollenwahl. Im Editor bleiben die einzelnen Andockpositionen erhalten; Nullstellungen werden nicht mit dem gemeinsamen Punkt verbunden.</p><p>Zum Testen verbindest du zwei SVG-Lines mit Eingängen der SVG LineBox und eine dritte SVG-Line mit einem Ausgang. Bei beiden Eingangsleitungen wählst du unter <strong>Animation → Richtungsquelle</strong> die <strong>Zahlen-Entität</strong> und trägst eine gültige Home-Assistant-Entity-ID ein. Enden die Eingangsleitungen an der SVG LineBox, werden ihre signierten Werte addiert. Beispiel: <code>1000</code> und <code>-300</code> ergeben <code>700</code>. Eine Leitung, die an der SVG LineBox beginnt, zählt am Eingang mit umgekehrtem Vorzeichen. Fehlende oder ungültige Zustände werden nicht mitgerechnet.</p><p>Stelle den Ausgangspunkt auf <strong>Ausgang</strong> und aktiviere den zunächst ausgeschalteten Haken <strong>Berechneten Wert weitergeben</strong>. Bei der Ausgangsleitung aktivierst du die Animation. Sie verwendet dann Vorzeichen und Betrag der Summe für Richtung und Geschwindigkeit. Mit <strong>SVG LineBox-Teiler (bei Übergabe)</strong> bestimmst du das Verhältnis: Bei <code>700</code> und Teiler <code>100</code> läuft die Linie mit 7 Zyklen/s. Ihre eigenen Linienfarben, Pfeilspitzen und die Linienart bleiben erhalten. Bei Summe <code>0</code> oder ohne gültigen Eingang hält die Animation an. Schaltest du die Weitergabe am Ausgang aus, nutzt die Leitung wieder ihre eigenen Animationseinstellungen.</p><p>Die Berechnung und Übergabe erfolgen normalerweise intern. Unter <strong>Zahlenhelfer-Ausgabe</strong> kannst du die Summe zusätzlich in einen <code>input_number</code>-Helfer schreiben, um sie in Home Assistant weiterzuverwenden. Die interne Übergabe bleibt aktiv. Es wird nur bei geändertem Summenwert geschrieben; ein Helfer, der zugleich Eingangsquelle derselben SVG LineBox ist, wird zur Vermeidung einer Rückkopplung abgelehnt. Der Wertebereich des Helfers muss zur möglichen Summe passen.</p><p>Die erste Version nutzt Zahlen-Entitäten an den Eingangsleitungen. Eine gesonderte Entitätssteuerung pro SVG LineBox-Anschluss ist noch nicht vorhanden.</p><p>Der frühere Palettenname „Linebox“ bleibt als Suchbegriff erhalten. Gespeicherte Projekte verwenden weiterhin den technischen Widget-Typ <code>linebox</code>; bestehende eigene Widget-Namen werden nicht verändert.</p>',19)])])}const b=n(s,[["render",d]]);export{c as __pageData,b as default};
